--
-- Structure for view `bills_with_vendor_creator`
--
DROP TABLE IF EXISTS `bills_with_vendor_creator`;

CREATE ALGORITHM=UNDEFINED DEFINER=`bdhatbela_admin`@`localhost` SQL SECURITY DEFINER VIEW `bills_with_vendor_creator`  AS SELECT `b`.`id` AS `id`, `b`.`bill_number` AS `billNumber`, `b`.`bill_date` AS `billDate`, `b`.`vendor_id` AS `vendorId`, `v`.`name` AS `vendorName`, `v`.`phone` AS `vendorPhone`, `v`.`address` AS `vendorAddress`, `b`.`created_by` AS `createdBy`, `u`.`name` AS `creatorName`, `b`.`status` AS `status`, `b`.`items` AS `items`, `b`.`subtotal` AS `subtotal`, `b`.`discount` AS `discount`, `b`.`shipping` AS `shipping`, `b`.`total` AS `total`, `b`.`paid_amount` AS `paidAmount`, `b`.`notes` AS `notes`, `b`.`history` AS `history`, `b`.`created_at` AS `createdAt`, `b`.`deleted_at` AS `deletedAt`, `b`.`deleted_by` AS `deletedBy` FROM ((`bills` `b` left join `vendors` `v` on(`v`.`id` = `b`.`vendor_id`)) left join `users` `u` on(`u`.`id` = `b`.`created_by`)) WHERE `b`.`deleted_at` is null ;

