CREATE ALGORITHM=UNDEFINED DEFINER=`bdhatbela_admin`@`localhost` SQL SECURITY DEFINER VIEW `employee_wallet_balances`  AS SELECT `u`.`id` AS `employeeId`, `u`.`name` AS `employeeName`, `u`.`role` AS `employeeRole`, round(coalesce(sum(case when `we`.`entry_type` in ('order_credit','order_reversal') and `o`.`created_at` >= '2026-03-31 18:00:00' then `we`.`amount_delta` when `we`.`entry_type` not in ('order_credit','order_reversal') and `we`.`created_at` >= '2026-03-31 18:00:00' then `we`.`amount_delta` else 0 end),0),2) AS `currentBalance`, round(coalesce(sum(case when `we`.`entry_type` = 'order_credit' and `o`.`created_at` >= '2026-03-31 18:00:00' then `we`.`amount_delta` else 0 end),0),2) AS `totalEarned`, round(abs(coalesce(sum(case when `we`.`entry_type` = 'payout' and `we`.`created_at` >= '2026-03-31 18:00:00' then `we`.`amount_delta` else 0 end),0)),2) AS `totalPaid`, coalesce(`active_wallet_orders`.`credited_orders`,0) AS `creditedOrders`, max(case when `we`.`entry_type` in ('order_credit','order_reversal') and `o`.`created_at` >= '2026-03-31 18:00:00' then `we`.`created_at` when `we`.`entry_type` not in ('order_credit','order_reversal') and `we`.`created_at` >= '2026-03-31 18:00:00' then `we`.`created_at` else NULL end) AS `lastActivityAt` FROM (((`users` `u` left join `wallet_entries` `we` on(`we`.`employee_id` = `u`.`id`)) left join `orders` `o` on(`o`.`id` = `we`.`source_order_id`)) left join (select `active_order_credits`.`employee_id` AS `employee_id`,count(0) AS `credited_orders` from (select `we`.`employee_id` AS `employee_id`,`we`.`source_order_id` AS `source_order_id` from (`wallet_entries` `we` join `orders` `o` on(`o`.`id` = `we`.`source_order_id`)) where `we`.`entry_type` in ('order_credit','order_reversal') and `o`.`created_at` >= '2026-03-31 18:00:00' group by `we`.`employee_id`,`we`.`source_order_id` having round(coalesce(sum(`we`.`amount_delta`),0),2) > 0) `active_order_credits` group by `active_order_credits`.`employee_id`) `active_wallet_orders` on(`active_wallet_orders`.`employee_id` = `u`.`id`)) WHERE `u`.`role` = 'Employee' AND `u`.`deleted_at` is null GROUP BY `u`.`id`, `u`.`name`, `u`.`role`, `active_wallet_orders`.`credited_orders` ;

